-- Intellix Platform V2: roles, permissions, LMS and client portal
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='SUPER_ADMIN') INSERT INTO Roles(RoleName,Description) VALUES('SUPER_ADMIN','Full platform control');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='ADMIN') INSERT INTO Roles(RoleName,Description) VALUES('ADMIN','Platform administrator');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='MANAGER') INSERT INTO Roles(RoleName,Description) VALUES('MANAGER','Business manager');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='SALES') INSERT INTO Roles(RoleName,Description) VALUES('SALES','Sales team');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='INSTRUCTOR') INSERT INTO Roles(RoleName,Description) VALUES('INSTRUCTOR','Academy instructor');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='STUDENT') INSERT INTO Roles(RoleName,Description) VALUES('STUDENT','Academy student');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='CLIENT') INSERT INTO Roles(RoleName,Description) VALUES('CLIENT','Company client');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='HR') INSERT INTO Roles(RoleName,Description) VALUES('HR','Human resources');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='FINANCE') INSERT INTO Roles(RoleName,Description) VALUES('FINANCE','Finance team');
IF NOT EXISTS (SELECT 1 FROM Roles WHERE RoleName='SUPPORT') INSERT INTO Roles(RoleName,Description) VALUES('SUPPORT','Support team');

IF OBJECT_ID('Permissions','U') IS NULL CREATE TABLE Permissions(PermissionID INT IDENTITY PRIMARY KEY,Code NVARCHAR(100) UNIQUE NOT NULL,Name NVARCHAR(120) NOT NULL,Description NVARCHAR(255),CreatedAt DATETIME DEFAULT GETDATE());
IF OBJECT_ID('RolePermissions','U') IS NULL CREATE TABLE RolePermissions(RolePermissionID INT IDENTITY PRIMARY KEY,RoleID INT NOT NULL FOREIGN KEY REFERENCES Roles(RoleID),PermissionID INT NOT NULL FOREIGN KEY REFERENCES Permissions(PermissionID),CONSTRAINT UQ_RolePermission UNIQUE(RoleID,PermissionID));
IF OBJECT_ID('ClientProfiles','U') IS NULL CREATE TABLE ClientProfiles(ClientProfileID INT IDENTITY PRIMARY KEY,UserID INT UNIQUE NOT NULL FOREIGN KEY REFERENCES Users(UserID),CompanyName NVARCHAR(160) NOT NULL,Industry NVARCHAR(100),Website NVARCHAR(255),Address NVARCHAR(500),Status NVARCHAR(30) DEFAULT 'active',CreatedAt DATETIME DEFAULT GETDATE());
IF OBJECT_ID('Courses','U') IS NULL CREATE TABLE Courses(CourseID INT IDENTITY PRIMARY KEY,Title NVARCHAR(180) NOT NULL,Slug NVARCHAR(200) UNIQUE NOT NULL,ShortDescription NVARCHAR(500),Description NVARCHAR(MAX),Thumbnail NVARCHAR(500),Price DECIMAL(12,2) DEFAULT 0,Level NVARCHAR(30) DEFAULT 'Beginner',Status NVARCHAR(30) DEFAULT 'draft',InstructorID INT NULL FOREIGN KEY REFERENCES Users(UserID),IsPublished BIT DEFAULT 0,CreatedAt DATETIME DEFAULT GETDATE(),UpdatedAt DATETIME DEFAULT GETDATE());
IF OBJECT_ID('Lessons','U') IS NULL CREATE TABLE Lessons(LessonID INT IDENTITY PRIMARY KEY,CourseID INT NOT NULL FOREIGN KEY REFERENCES Courses(CourseID),Title NVARCHAR(180) NOT NULL,Content NVARCHAR(MAX),VideoURL NVARCHAR(500),ResourceURL NVARCHAR(500),SortOrder INT DEFAULT 0,IsPreview BIT DEFAULT 0,CreatedAt DATETIME DEFAULT GETDATE());
IF OBJECT_ID('Enrollments','U') IS NULL CREATE TABLE Enrollments(EnrollmentID INT IDENTITY PRIMARY KEY,StudentID INT NOT NULL FOREIGN KEY REFERENCES Users(UserID),CourseID INT NOT NULL FOREIGN KEY REFERENCES Courses(CourseID),Status NVARCHAR(30) DEFAULT 'active',ProgressPercent DECIMAL(5,2) DEFAULT 0,EnrolledAt DATETIME DEFAULT GETDATE(),CompletedAt DATETIME NULL,CONSTRAINT UQ_StudentCourse UNIQUE(StudentID,CourseID));
IF OBJECT_ID('Assignments','U') IS NULL CREATE TABLE Assignments(AssignmentID INT IDENTITY PRIMARY KEY,CourseID INT NOT NULL FOREIGN KEY REFERENCES Courses(CourseID),Title NVARCHAR(180) NOT NULL,Instructions NVARCHAR(MAX),DueAt DATETIME NULL,MaxMarks DECIMAL(8,2) DEFAULT 100,CreatedAt DATETIME DEFAULT GETDATE());
IF OBJECT_ID('Submissions','U') IS NULL CREATE TABLE Submissions(SubmissionID INT IDENTITY PRIMARY KEY,AssignmentID INT NOT NULL FOREIGN KEY REFERENCES Assignments(AssignmentID),StudentID INT NOT NULL FOREIGN KEY REFERENCES Users(UserID),AnswerText NVARCHAR(MAX),AttachmentURL NVARCHAR(500),Marks DECIMAL(8,2),Feedback NVARCHAR(MAX),Status NVARCHAR(30) DEFAULT 'submitted',SubmittedAt DATETIME DEFAULT GETDATE(),GradedAt DATETIME NULL,CONSTRAINT UQ_AssignmentStudent UNIQUE(AssignmentID,StudentID));
